        if books[i] == bank[j]:
            matched.append(books[i]); i += 1; j += 1
        elif books[i] < bank[j]:
            only_a.append(books[i]); i += 1
        else:
            only_b.append(bank[j]); j += 1
    return matched, only_a + books[i:], only_b + bank[j:]

def best_pair(prices, budget):
    p = sorted(prices)
    l, r, best = 0, len(p) - 1, -1
    while l < r:
        s = p[l] + p[r]
        if s <= budget:
            best = max(best, s)
            l += 1
        else:
            r -= 1
    return best

def pair_sum(nums, target):
    l, r = 0, len(nums) - 1
    while l < r:
        s = nums[l] + nums[r]
        if s == target:
            return (l, r)
        if s < target:
            l += 1
        else:
            r -= 1
    return None
